<?php use App\Core\Db; $pdo=Db::pdo(); $id=(int)$_GET['id']; $u=\App\Core\Auth::user(); $d=$pdo->query("SELECT * FROM cpms_approval_documents WHERE id=".$id)->fetch(); $lines=$pdo->query("SELECT * FROM cpms_approval_lines WHERE document_id=".$id." ORDER BY line_order")->fetchAll(); ?><div><h2><?php echo h($d['title']);?></h2><div><?php echo nl2br(h($d['content']));?></div><?php foreach($lines as $l):?><div><?php echo h($l['role_type'].' '.$l['approver_name'].' '.$l['line_status'].' '.$l['acted_at']);?></div><?php endforeach; ?><?php foreach($lines as $l){if((int)$l['approver_id']==(int)$u['id']&&$l['line_status']==='PENDING'){?><form method="post" action="?r=approval_decide"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="id" value="<?php echo $id;?>"><button name="action" value="approve">승인</button><input name="reject_reason"><button name="action" value="reject">반려</button></form><?php }} ?></div>